            ['T3', 'API keys leak via DB, logs, or exports', 'Keys live only in .env; never written to any table, log line, or export path; export bundle is key-free by schema', 'Export snapshot test + log scrubber test'],
            ['T4', 'Local session hijack from another tab/app', 'Passphrase-gated session cookie, HttpOnly, SameSite=Lax, 12-hour expiry, bound to loopback use', 'Auth middleware unit tests'],
